    "titleTh": "The Legend of Heroes มังกรหยก : คัมภีร์นพเก้า (2026) พากย์ไทย Part 2",
    "titleEn": "The Legend of Heroes มังกรหยก : คัมภีร์นพเก้า (2026) พากย์ไทย Part 2",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/08/999.png",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/08/999.png",
    "videoUrl": "https://torbo007.com/embed/40437877d64bca8e2e1e4a14e509fe9a",
    "sourceType": "embed",
    "description": "เรื่องย่อ: มังกรหยก : คัมภีร์นพเก้า🌸🍃✨\r\n จากเรื่องราวความรักและความแค้นของหญิงสาวคนหนึ่ง ที่สูญเสียครอบครัว และเมื่อเธอได้เข้ามาพัวพันกับคัมภีร์วิชาชั้นสูง บอกเล่าเรื่องราวของหญิงสาวคนหนึ่ง เหมยรั่วฮัว ที่สูญเสียทุกอย่างไปแบบกระทันหัน พร้อมการสังหารหมู่จากตระกูลขุนนาง และนี่เองจึงเป็นจุดเริ่มต้นการแก้แค้น พร้อมแรงผลักดันทว่าโชคชะตากลับทำให้เธอต้องเข้ามาเป็นศิษย์คนสำคัญของสำนักหลวงแห่งเกาะเถาฮัว จากความแค้นกลับทำให้เธอเปลี่ยนชื่อพร้อมชีวิตใหม่ขึ้นมาอีกครั้งพร้อมอยู่กับชื่อ เหมยเซาเฟิง และการใช้ชีวิตครั้งใหม่ ทว่าเมื่อเธอได้เข้ามาอยู่กับ เฉินเสวียนเฟิง ใหญ่ของสำนักที่เขาแอบชอบเธอตั้งแต่แรกพบ ทว่า เหมยรั่วฮัว กลับติดอยู่กับการฝึกฝนการต่อสู้อย่างไร้ที่ติ เพื่อนำความสามารถเข้ามาแก้แค้นอย่างสมบูรณ์แบบ ทว่าเมื่อทุกอย่างกลับทำให้เธอเข้ามาสู่โคจรอันโหดร้าย พร้อมการก้าวเข้ามาสู่อำนาจและเส้นทางการต่อสู้เพียงเท่านั้น จนกระทั่งจุดเปลี่ยนชะตากรรม กลับทำให้ทั้งสองเข้ามาพัวพันกับความลับเกี่ยวกับ (คัมภีร์นพเก้า) ซึ่งนำพาอุปสรรค และการแลกเปลี่ยนชีวิตของพวกเขาทั้งสองไปตลอดกาล \r\n \r\n",
