    "titleTh": "OUTER BANKS สมบัติลับเอาเทอร์แบงค์ส ซีซัน 5 (2026) พากย์ไทย EP.1-10",
    "titleEn": "OUTER BANKS สมบัติลับเอาเทอร์แบงค์ส ซีซัน 5 (2026) พากย์ไทย EP.1-10",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/08/7-1.png",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/08/7-1.png",
    "videoUrl": "https://torbo007.com/embed/0925139b908ccc06c7a5abf26b95c2c9",
    "sourceType": "embed",
    "description": "เรื่องย่อ: สมบัติลับเอาเทอร์แบงค์ส ซีซัน 5\r\n “เมื่อเดอะแก๊งต้องออกเดินทางล่าสมบัต และนี่เองจึงเป็นจุดเริ่มต้นของความวุ่นวายเหล่านี้” บอกเล่าเรื่องเรื่องราวจากเหตุการณครั้งก่อน เมื่อพวกเขาต่างต้องเข้ามาจบเจอการสูญเสียครั้งหใญ่ จนทำให้มีคนเสียชีวิตจากน้ำมือของคนคนหนึ่งเพียงเท่านั้น แต่แล้วสถานการณ์เลวร้ายมากยิ่งขึ้นเมื่อ แชนดเลอร์ ยังคงหลบหนี แต่ในขณะเดียวกันนั้น ก็ไล่ล่าพวกเขาอย่างไม่ลดละ ส่วนเหล่าผู้คนที่ยังคงพยายามกีดกันไม่ให้กลับไปใช้ชีวิตที่บ้านเกิดได้อีก ทว่าเหล่าศัตรูกลับเข้ามารุมล้อมจากทุกทิศทาง พร้อมทำให้เดอะแก๊งจึงต้องกลับมารวมตังกันอีกครั้ง แม่ต่างจะไม่เต็มใจกันเท่าไหร่นัก ซึ่งเคยเป็นศัตรูสำคัญของพวกเขา ก็ต้องเข้ามาร่วมมือกันอย่างไม่เต็มใจ ความสัมพันธ์ระหว่างทุกคนจึงเต็มไปด้วยความระแวงและความขัดแย้ง แต่พวกเขาไม่มีทางเลือกอื่นหากต้องการเอาตัวรอด และนี่ก็เป็นอีกหนึ่งภารกิจสุดท้ายที่ต่างต้องพบเจอกับการผจญภัยของกลุ่ม พร้อมยังเป็นการเดิมพันครั้งใหญ่ ของมิตรภาพ ความรัก การแก้แค้น และการล่าสมบัติเดินทางครั้งสุดท้าย พร้อมบทสรุปเรื่องราวทุกอย่าง  พวกเขาจะได้กลับบ้านพร้อมชัยชนะ หรือจะต้องสูญเสียทุกอย่างไปพร้อมกัน \r\n",
