    "description": "เรื่องย่อ: house of the dragon3\r\n เมื่อเกิดเหตุการณ์สงครามราชศ์วงทาร์แกเรียนที่กำลังเกิดความรุนแรงมากขึ้นเรื่อยๆ เพียงเพระาการขัดแย้งของ แบล็ก และฝ่ายของ กรีน ที่เป็นฝ่ายสนับสนุนได้เข้ามาลุมลาม จนกลายเป็นสงครามการแย่งชิงชิงบัลลังก์ขึ้นมาอีกครั้ง และซีซันนี้กลับเป็นการสูญเสียของทุกฝ่ายที่เลือกเดินทางเข้าสู่สงครามอย่างไม่มีทางหวนกลับคืนมา พร้อมเหล่ากองทัพ พันธมิตร และเหล่ามังกรถูกจับเข้ามาสู่สนามรบ ในขณะที่ความสัมพันธ์ภายในตระกูล ทาร์แกเรียน ที่เริ่มแตกร้าวมากขึ้นเรื่อยๆ ทั้งการทรยศ การแก้แค้น รวมไปถึงการต่อสู้เพื่อแย่งชิงอำนาจกลายเป็นกลายเป็นหัวใจที่สำคัญมากที่สุด สุดท้ายแล้วซีรี่ย์เรื่องนี้จะจบลงอย่างไรเราไปรับชมพร้อมๆกันค่ะ>>\r\n",
