    "description": "เรื่องย่อ สายลับซ่อนเร้น | Unfamiliar\r\n วันนี้เราจะมาป้ายยาซีรี่ยืเรื่อใหม่กันอีกแล้วกับเรื่อง “Unfamiliar สายลับซ่อนเร้น” พร้อมเป็นการบอกเล่าเรื่องราวของ  “ไซม่อน” ตื่นขึ้นมาในเมืองแปลกหน้าโดยไร้ซึ่งความทรงจำ เขากลับพบว่าตัวเองกำลังถูกตามล่าจากทั้งหน่วยงานรัฐและองค์กรลับที่ไม่เปิดเผยตัวตน เบาะแสเพียงอย่างเดียวที่เขามีคือรอยสักปริศนาบนร่างกาย ซึ่งเชื่อมโยงกับภารกิจลับระดับชาติ ระหว่างการหลบหนี เขาได้ร่วมมือกับ “เมเร็ต” นักข่าวสาวที่กำลังสืบคดีการหายตัวไปของสายลับหลายราย อดีตที่ค่อย ๆ ถูกเปิดเผยกลับเต็มไปด้วยความรุนแรงและการทรยศหักหลัง ยิ่งเขารู้ความจริงมากเท่าไร อันตรายก็ยิ่งคืบคนเข้ามาใกล้มากขึ้น ท่ามกลางการไล่ล่า ความสัมพันธ์ระหว่างเขากับเมเร็ตค่อย ๆ ก่อตัวขึ้นอย่างไม่รู้ตัวขณะที่ศัตรูตัวจริงอาจซ่อนตัวอยู่ใกล้กว่าที่คิด ไซม่อนจึงต้องเลือกระหว่างการค้นหาตัวตนที่แท้จริงกับความรัก และหน้าที่ที่อาจต้องแลกด้วยทุกสิ่งที่เขามี สำหรับซีรี่ย์เรื่องนี้ก็พร้อมออกอากาศในวันที่ 5 กุมภาพันธ์ 2026 นี้เป็นต้นไป\r\n",
