    "sourceType": "embed",
    "description": "เรื่องย่อ:นักสู้ยูทูปเบอร์\r\n บอกเล่าเรื่องราวของ ชิมูระ โคตะ เด็กหนุ่มชั้นมัธยมปลายที่มีชีวิตและการเป็นอยู่ค่อยข้างยากลำบาก ทั้งต้องหาเงินส่งตัวเองเรียน การรักษาแม่ที่กำลังป่วยหนัก และการถูกรังแกจากเพื่อนร่วมห้องที่พยายามกลั้นแกล้งเขสอยู่ตลอดเวลา ในความสิ้นหวังและหมดหนทางเลือกลับทำให้เขาเลือการขึ้นชกแมตช์สำคัญกับเพื่อนร่วมห้องอีกครั้งพร้อมการถ่ายทอดสดโดยบังเอิญ และนี่เองจึงเป็นจุดเปลี่ยนทำให้เขาเป็นที่รู้จักของวงการมวยขึ้นมาอีกครั้ง พร้อมทุกอย่างกลับทำให้เขาพบว่าการต่อสู้สามารถสร้างรายได้เพื่อเปลี่ยนแปลงชีวิตของเขาได้ หลังจากนี้ โคตะ จึงเลือกการสตรีมมิงของตัวเอง พร้อมการฝึกฝนเทคนิคการต่อสู้จากคริปวิดีโอปริศนาบนอินเทอรืเน็ต เขาจึงค่อยๆพัฒนาจากเด็กหนุ่มผู้ไร้พลัง กลายเป็นนักต่อสู้ที่ต้องเผชิญหน้ากับคู่ต่อสู้ที่แข็งแกร่งขึ้นเรื่อยๆ ท่ามกลางโลกออนไลน์ที่เต้มไปด้วยชื่อเสียง เงินทอง และความกอดันจากคนดู เด็กหนุ่มคนนี้จะเลือกอะไรเราไปรับชมพร้อมๆกันค่ะ\r\n",
