    "titleTh": "See You at Work Tomorrow! เจอกันที่ออฟฟิศพรุ่งนี้นะ! (2026) พากย์ไทย EP.1-12",
    "titleEn": "See You at Work Tomorrow! เจอกันที่ออฟฟิศพรุ่งนี้นะ! (2026) พากย์ไทย EP.1-12",
    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/06/99-7.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/06/99-7.jpg",
    "videoUrl": "https://torbo007.com/embed/e963f04ecfa7cf397bdb6768f74ce448",
    "sourceType": "embed",
    "description": "เรื่องย่อ: เจอกันที่ออฟฟิศพรุ่งนี้นะ! | 내일도 출근\r\n เล่าเรื่องของ ชาจียุน พนักงานสาวที่ทำงานมาเข้าสู่ปีที่ 7 จนเริ่มรู้สึกหมดไฟทั้งในหน้าที่การงานและชีวิตส่วนตัว เมื่อเธอต้องเผชิญหน้ากับความกดดันในบริษัท และการเปลี่ยนแปลงภายในองค์กร จนทำให้ ชาจียุนย้ายเข้ามทำงานใต้การดุแลของห้วหน้าหนุ่มผู้แสนเย็นชาอย่าง คังชีอู ที่เขากลับมองว่าเธอเป็นคนเลวร้ายน้อยที่สุด ในสถานการณ์ที่เขากำลังเผชิญอยู่ แม้ว่า คังชีอู ผู้จัดการที่ขึ้นชื่อในเรื่องเข้มงวด และเข้ายากสุดๆ ทว่าเมื่อทั้งสองต้องจำยอมร่วมงานกันอย่างใกล้ชิดมากขึ้นเรื่อยๆ จากความสัมพันธ์ที่เริ่มต้นขึ้นมาจากความอึดอัดและการปะทะกันอยู่ตลอดเวลาจากการปะทะคารม กลับค่อยๆพัฒนาเป้นความสัมพันธ์มากขึ้นเรื่อยๆ และทุกอย่างกลับเป็นความเข้าใจ ความไว้วางใจ พร้อมกำลังใจอันสำคัญให้ซึ่งกันและกัน แต่แล้วท่ามกลางความวุ่นวายของวัยทำงาน ความฝันในอาชีพ และความรักที่ค่อยๆ ก่อตัวมากขึ้นเรื่อยๆอย่างไม่คาดคิด\r\n",
