    "sourceType": "embed",
    "description": "เรื่องย่อ: คมดาบสยบพิภพ | 太平年  \r\n บอกเล่าเรื่องราวการแย่งชิงอำนาจเพื่อที่จะทำให้คนเองเป็นในที่สุด บอกเล่าเรื่องราวที่เกี่ยวกับ ห้าราชวงศ์สิบอาณาจักรอันวุ่นวาย ท่ามกลางความวุ่นวายและความสับสน โดยมีบ่าวสาวทั้งสามคนที่พยายามผ่านพ้นเรื่องราวในชีวิตและพร้อมต่อสู้กับกลุ่มผู้มีอำนาจที่กำลังกดขี่กลุ่มยากจน เพราะเหตุนี้เองจึงทำให้คนทั้งสามอย่าง เฉียนหงชู จ้าวควงหยิน และกัวหรง ได้ก้าวขาเข้ามาต่อสู้กับอุดมการณ์ที่แน่วแน่ในครั้งนี้ ในการต่อสู้ครั้งนี้กลับทำให้จ้าวควงหยินยังไม่ประสบความสำเร็จอีกเช่นเคยเพียงเพราะเขาขาดประบการณ์ ในครั้งนี้พวกเขายังตั้งมั่นที่จะเข้ามาร่วมต่อสู้และพร้อมเผชิญกับความยากลำบากทางการเมืองในครั้งนี้ ทว่าเรื่องราวที่ดุเดือดในสงครามครั้งนี้จะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ สานต่อควงามสนุกและความเข้มข้นไปพร้อมๆกันกับเราต่อได้ที่ G4 แหล่งรวมซีรี่ย์ออนไลน์ที่เรามีมากกว่าสามพันเรื่อง บอกเลยว่าครบจบในที่เดียวจริงๆ       \r\n",
