    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/07/1784631990001.jpg",
    "videoUrl": "https://torbo007.com/embed/ea8d508c9b1eef7de812ba3b2d1112e3",
    "sourceType": "embed",
    "description": "เรื่องย่อ: (เพื่อน (ห้าม) ตาย)\r\n เรียกได้ว่าเป็นอีกหนึ่งเรื่องที่น่าติดตามชมกันเป็นอย่างมาก กับซีรี่ย์ฟอร์มยักษ์ พร้อมการ บอกเล่าเรื่องราวของ เด็บบี้ และ จูดิธ สองเพื่อนชี้ที่เชื่อมาโดยตลอดว่าต่างฝ่ายต่างต้องไม่มีความลับต่อกันและกัน จนกระทั่งวันหนึ่งทั้งสองต่างรู้ถึงความจริง เมื่อ จูดิธ ที่มีชีวิตอีกด้านในนามของนักฆ่ามืออาชีพที่ต่างไม่อยากมีเรื่องบาดหมางกับเขามาโดยตลอด แต่แล้วเมื่อภาระกิจสั่งสังหารครั้งล่าสุดที่อยากจะเหลือเชื่อ เพียงเพราะเขาได้ค้นพบรายชื่อหนึ่งขึ้นมา จากการไล่ล่าศัตรูจากอดีตกลับมาอีกครั้ง พร้อมดึงให้เขาเข้ามาสู่เกมเอาชีวิตรอดที่ไม่มีทางหันหลังกลับมาได้อีกครั้ง จากเพื่อนธรรมดาที่มช้ชีวิตอย่างเรียบง่าย ทั้งสองต้องกลายเป็นผู้หลบหนี พร้อมเดินทางข้ามประเทศเพื่อการหนีเจ้าหน้าที่รัฐ องค์กรนักฆ่า และอาชญากรรมที่หมายเอาชีวิตของพวกเธอ ในระหว่างการการหลบหนี ความลับที่ถูกเก็บซ่อนเอาไว้ในรอบหลายปีค่อยๆถูกเปิดเผยขึ้นมาเรื่อยๆ พร้อมบททดสอบของมิตรภาพ ที่เลือกให้ทั้งสองต้องมาพบเจอกับความจริง และการอยู่นรอดจากเหตุการณ์ครั้งนี้  \r\n",
