    "sourceType": "embed",
    "description": "เรื่องย่อ-ชำระแค้นทรชน\r\n  “เมื่อความชิปหายและความบ้าคลั่งที่กำลังเริ่มต้นขึ้นกับเดอะแก๊งผู้กล่าของเมือง” จากความสงบสุขของคนในเมืองใหญ่ที่ต้องมาพบเจอกับความชิปหายอีกครั้ง และในขณะที่เจ้าหน้าที่ตำรวจที่พยายามออกล่าตามหาตัวผู้ก่อเหตุ และ “ลีน่า” เมืองก็ได้แฝงตัวเข้ามาอยู่ในกลุ่มของมาม่าซ่อง เพื่อที่จะฝ่าฝันภารกิจที่เสี่ยงเป็นเสี่ยงตายมากในตอนนี้ แต่งานครั้งแรกของเธอกับพังไปอย่างง่ายดาย แต่สุดท้ายแล้วทุกอย่างกลับนำพาให้เธอได้กลับมาปกกับความลึกลับเหล่านี้อีกครั้ง สุดท้ายแล้วชีวิตของหญิงสาวคนนี้จะจบลงอย่างไรเราไปรับชมพร้อมๆกันค่ะ หากเพื่อนๆคนไหนที่กำลังมองหาซีรี่ย์เรื่องใหม่ๆเอาไว้รับชมก็ไม่ควรพลาดกับ G4 เว็บดูซีรี่ย์ออนไลน์ที่เรามีมากกว่าสามพันเรื่องบอกเลยว่าห้ามพลาด>>\r\n",
