    "description": "เรื่องย่อ-ซาร่าห์ เริ่ดลวงโลก | 레이디 두아 \r\n บอกเรื่องราวของ “ซาร่าห์ คิม” คือผู้บริหารสาวมากความสามารถที่ตัดสินใจปลุกชีพแบรนด์กระเป๋าชื่อดังของครอบครัวขึ้นมาอีกครั้ง ชีวิตการทำงานของเธอเต็มไปด้วยความกดดันและอุปสรรค โดยเฉพาะเมื่อเธอรู้สึกว่ามีใครบางคนคอยติดตามเธออยู่ตลอดเวลา ไม่นานนัก บุคคลลึกลับก็เริ่มเข้ามาใกล้ตัวเธอมากขึ้น จนเธอเริ่มไม่แน่ใจว่าใครคือมิตรและใครคือศัตรู ในขณะเดียวกัน มูคยอง ชายหนุ่มผู้เย็นชาแต่แฝงไปด้วยความสามารถในฐานะสายลับ ได้รับมอบหมายให้สืบคดีการตายปริศนา เบาะแสทุกอย่างกลับพาเขามาหยุดอยู่ที่ “ซาร่าห์ คิม” หญิงสาวที่ดูเหมือนจะมีความลับซ่อนอยู่มากมาย ยิ่งสืบลึกลงไป ความจริงยิ่งซับซ้อนและอันตรายเกินกว่าที่ทั้งสองคาดคิด การพบกันของนักธุรกิจสาวและสายลับหนุ่ม กลายเป็นจุดเริ่มต้นของชะตากรรมที่ไม่อาจหลีกเลี่ยง เพราะเธอต้องเผชิญกับอดีตที่เธอพยายามหลบหนีมาตลอดชีวิต ขณะที่มูคยองต้องเลือกระหว่างหน้าที่กับความรู้สึกที่เริ่มก่อตัวขึ้นในใจ คดีฆาตกรรมปริศนาครั้งนี้จะทำให้ชีวิตของซาร่าห์พังทลาย หรือจะนำพาเธอไปสู่ความจริงที่ไม่เคยรู้มาก่อน \r\n    \r\n",
