    "description": "เรื่องย่อ: บูรพาอาถรรพ์ | 동궁\r\n เมื่อเหตุการณ์แปลกประหลาด และเกิดการตายขึ้นมาอย่างลึลกลับ ภายใต้ตำหนักบูรพาวึ่งเป็นสถานที่ประทับขององค์รัชทายาท ที่พยายามให้ กูชอน ชายหนุ่มผู้มีความสามารถเดินทางเข้ามาในท่ามกลางโลกมนุษย์ กับโลกหวิญญาณ และการใช้ดาบปราบภูตผี พร้อมการเข้ามาร่วมมือกับ แซงกัง นางกำนัลสาวผู้มีพรสวรรค์ในการได้ยินเสียง และสื่อสารกับวิญญาณได้เป็นอย่างดี แม้ว่าความสามถวิเศษเหล่านี้กลับทำให้เธอต้องพบกับคำสาปที่ติดตัวมาตั้งแต่กำเนิด ทุกคนต่างต้องมาพบเจอกับจุดจบครั้งยิ่งใหญ่ ครั้งนี้พวกเขาต่างร่วมมือกันค้นหาความจริงทุกอย่างที่ถูกเก็บซ่อนเอาไว้ ต่างก็หวังเพื่อเข้ามาเปิดโปรงความจริง ความลับอันดำมืดของตำหนักบูรพา ซึ่งเป็นสถานที่ที่ประทับขององค์รัชทายาทมาหลายอายุคน และยิ่งมากกว่านั้นคือ เมื่อความจริงเริ่มปรากฎขึ้นมากเท่าไหร่ พวกเขาทั้งสามต่างต้องเผชิญหน้ากับวิญญาณอาฆาต พร้อมเหล่าอดีตนักโทษร้าย ที่กำลังหวนกลับคืนมากอีกครั้ง แต่แล้วจุดจบทุกอย่างจะเป็นอย่างไรเราไปรับชมพร้อมๆกันค่ะ      \r\n",
