    "sourceType": "embed",
    "description": "เรื่องย่อ-ปรารถนาอันตราย 3\r\n เมื่อความเหงาทุกอย่างกลับถูกครอบคลุม “เจคอบ” ถูกพบว่าเสียชีวิตอย่างปริศนาก่อนวันแต่งงาน เหตุการณ์ที่ควรเป็นวันแห่งความสุขกลับกลายเป็นโศกนาฏกรรมที่ทำให้ทุกคนตกอยู่ในความหวาดระแวง\r\n“นันดี” ถูกดึงเข้าไปพัวพันกับคดีฆาตกรรมครั้งนี้ และต้องเผชิญกับเรื่องอื้อฉาวที่ค่อย ๆ เปิดโปงความลับของผู้คนรอบตัว ขณะที่นักสืบ “ทูโซ” เริ่มสืบสวนอย่างจริงจัง หลักฐานต่าง ๆ ก็พาไปสู่ความจริงที่ซับซ้อนและอันตรายยิ่งขึ้น ความตึงเครียดระหว่าง เจคอบ, ลีโอนาร์ด และวูโย กลับมาปะทุอีกครั้ง พร้อมความแค้นจากอดีตที่ยังไม่จบสิ้น ยิ่งความจริงถูกเปิดเผยมากเท่าไร ความสัมพันธ์ของทุกคนก็ยิ่งแตกร้าวมากขึ้น เบื้องหลังความรักและความใคร่ กลับซ่อนการทรยศและแผนการล้างแค้นที่รอวันเปิดเผย ผู้คนที่ดูเหมือนไม่เกี่ยวข้อง กลับมีความลับที่เชื่อมโยงกับคดีฆาตกรรมครั้งนี้ ในโลกที่เต็มไปด้วยความหลอกลวง ไม่มีใครบริสุทธิ์อย่างที่เห็น และเมื่อเกมแห่งอำนาจและความปรารถนาเริ่มขึ้นอีกครั้ง ทุกการตัดสินใจอาจนำไปสู่หายนะ พร้อมการเปิดโปรงความจริงที่เป็นเพียงแค่หนึ่งเดียวอาจทำลายชีวิตของทุกคนตลอดกาล ทว่าบทสรุปของเรื่องราวเหล่านี้จะเป้นอย่างไรเราไปรับชมพร้อมๆกันค่ะ \r\n",
