    "sourceType": "embed",
    "description": "พล็อตเรื่อง รักนี้มงลง | 21세기 대군 부인 \r\n เมื่อเรื่องราวความรักของ“ซองฮีจู” ทายาทสาวตระกูลมหาเศรษฐี ผู้มีชีวิตที่เพียบพร้อมทุกอย่าง ยกเว้นเพียง “ความหมายของหัวใจ” ที่เธอไม่เคยค้นพบ เธอตัดสินใจก้าวเข้าสู่เกมชีวิตครั้งใหญ่ ด้วยการแต่งงานตามสัญญากับ “อีอัน” องค์ชายลำดับที่สอง ผู้สูงศักดิ์แต่ไร้อิสระ ความสัมพันธ์ที่เริ่มต้นจากผลประโยชน์ กลายเป็นพันธนาการที่ทั้งสองไม่อาจหลีกหนี ต่อหน้าสังคม พวกเขาคือคู่รักที่สมบูรณ์แบบ แต่เบื้องหลังกลับเต็มไปด้วยแรงกดดันและความลับ กฎเกณฑ์ของราชวงศ์และสายตาผู้คน กลายเป็นกรอบที่บีบรัดหัวใจของทั้งคู่ให้แคบลงทุกวัน เมื่อความใกล้ชิดเริ่มเปลี่ยน “ข้อตกลง” ให้กลายเป็น “ความรู้สึก” ความสัมพันธ์ก็เริ่มสั่นคลอน อดีตที่ตามหลอกหลอน และผู้คนรอบตัวที่แฝงด้วยเจตนา กลับยิ่งทำให้ทุกอย่างซับซ้อนยิ่งขึ้น ระหว่างหน้าที่ที่ต้องรักษา กับหัวใจที่เริ่มเรียกร้องความจริง พวกเขาต้องเลือกเพียงหนึ่งเดียว เส้นทางของความรักครั้งนี้ จึงไม่ใช่เพียงเรื่องของสองคน แต่คือเกมอำนาจที่เดิมพันด้วยชีวิต และท้ายที่สุด “มงกุฎแห่งความสมบูรณ์แบบ” อาจไม่ใช่สิ่งสูงค่า…แต่อาจเป็นคำสาปที่ผูกมัดหัวใจของพวกเขาตลอดไป\r\n",
