    "videoUrl": "https://torbo007.com/embed/068c0a4f75185d23ffeb72eec4115b6c",
    "sourceType": "embed",
    "description": "เรื่องย่อ 프링 피버 ใบไม้ผลิที่รอคอย\r\n แวะมาป้ายยาซีรี่ย์เรื่องใหม่กันอีกแล้วกับเรื่อง “Spring Fever ใบไม้ผลิที่รอคอย” ที่พร้อมจะเข้ามาบอกเล่าเรื่องราวความรักที่กำลังผลิบานและได้กลับมาอีกครั้ง แต่ในบางความทรงจำที่ถูกเก็บซ่อนเอาไว้มานานแสนนานแต่ก็เริ่มเข้ามาผลิบานอีกครั้ง ซีรี่ย์เรื่องนี้จะเป้นการบอกเล่าเรื่องราวของหญิงสาว ฮันซออึน หญิงสาววัยทำงานที่ต้องพยายามดิ้นรนเพื่อที่จะมรชีวิตรอดไปในแต่ละเดือน เมื่อการตัดสินใจครั้งยิ่งใหญ่ของคนในครัวที่ต้องย้ายข้าวของออกมาเพื่อที่จะปักหลังอยู่ในหมู่บ้านติดทะเล และนี่เองจึงทำให้เธอต้องกลับมายังบ้านเกิดอีกครั้ง และตนเองต้องมาพบกับเรื่องราวความเจ็บปวดในอดีตและต้องเผชิญหน้ากับมัน ทุกอย่างที่นำพาให้ความรู้สึกของเธอกลับมาอยู่จุดๆเดิมอีกครั้ง แต่ด้วยความวุ่นวายและความสับสนที่ทำให้เธอต้องต้องได้มาพบกับ อีโดฮยอน ชายหนุ่มผู้เย็นชายและเขาต้องมาพบกับความบอบซ่ำของเธอ จากชายหนุ่มผู้เข้มขรึมที่กลับกลายเป็นผู้ชายที่อ่อนหวานอีกครั้ง แต่ด้วยความใกล้ชิดที่ทำให้ทั้งสองเกิดความรู้สึกดีๆอีกครั้ง และแล้วเรื่องราวความรู้สึกของคนทั้งสองจะเป็นอย่างไรเราไปรับชมพร้อมกันค่ะ สานต่อความสนุกไปพร้อมกันกับพวกเราได้ที่ G4 แหล่งรวมซีรี่ย์ออนไลน์ ครบ จบ ในที่เดียว \r\n",
