    "sourceType": "embed",
    "description": "พล็อตเรื่อง:สังเวียนเกียรติยศ\r\n เมื่อเรื่องราวเกิดขึ้นกับ“นิฮาล ซิงห์” นักมวยดาวรุ่งผู้ถูกคาดหวังสู่เวทีโอลิมปิก เสียชีวิตอย่างลึกลับ เหตุการณ์นี้กลายเป็นจุดเริ่มต้นที่ค่อย ๆ เปิดโปงความจริงอันดำมืด สองพี่น้องที่เคยบาดหมาง จำเป็นต้องหันกลับมาร่วมมือกัน เพื่อตามหาคำตอบของการตายครั้งนี้ พร้อมเผชิญหน้ากับพ่อของตนเอง โค้ชมวยชื่อดังผู้กุมความลับในอดีต ระหว่างการสืบสวน พวกเขาถูกดึงเข้าสู่โลกเบื้องหลังของวงการกีฬา ที่เต็มไปด้วยอิทธิพล เงินก้อนโต และการล็อกผลการแข่งขัน ซึ่งเชื่อมโยงถึงเครือข่ายผู้มีอำนาจ ความ ทะเยอทะยาน ความโกรธ และแรงแค้น ค่อย ๆ บั่นทอนความสัมพันธ์ในครอบครัว จนการค้นหาความจริง กลายเป็นการต่อสู้ทางจิตใจที่เดิมพันด้วยชีวิต ท้ายที่สุด “เกียรติยศ” ไม่ได้ถูกตัดสินแค่ในสังเวียน แต่ยังหมายถึงการยืนหยัดเพื่อศักดิ์ศรี ครอบครัว และความถูกต้อง แม้ว่าบทสรุปอาจไม่มีผู้ชนะอย่างแท้จริง\r\n",
