    "videoUrl": "https://torbo007.com/embed/f9af36550cb7ee2d32703985a5f4b5d3",
    "sourceType": "embed",
    "description": "เรื่องย่อ:เบอร์ลินกับภาพเขียนของดาวินชี\r\nเล่าเรื่องราวการกลับมาของ “เบอร์ลิน” จอมโจรอัจฉริยะผู้เต็มไปด้วยเสน่ห์และเล่ห์เหลี่ยม\r\nเมื่อเขาได้รวมทีมโจรคู่ใจเพื่อวางแผนขโมยภาพวาดระดับโลกของเลโอนาร์โด ดาวินชี\r\nเป้าหมายสำคัญคือภาพ “Lady with an Ermine” ที่ถูกเก็บรักษาไว้อย่างแน่นหนา\r\nภารกิจครั้งนี้ไม่ได้มีเพียงเรื่องเงินทอง แต่ยังเกี่ยวข้องกับการล้างแค้นในอดีต\r\nเบอร์ลินต้องเผชิญหน้ากับเหล่าผู้มีอำนาจที่พร้อมทำทุกอย่างเพื่อหยุดเขา\r\nระหว่างแผนปล้นสุดซับซ้อน ความรักและการหักหลังก็ค่อย ๆ ก่อตัวขึ้นในทีม\r\nสมาชิกแต่ละคนต่างมีความลับที่อาจทำให้ภารกิจล่มสลายได้ทุกเมื่อ\r\nยิ่งเข้าใกล้เป้าหมายมากเท่าไร อันตรายและเกมจิตวิทยาก็ยิ่งทวีความเข้มข้น\r\nท้ายที่สุดเบอร์ลินจะสามารถพาทีมรอดจากแผนการสุดเสี่ยงครั้งนี้ได้หรือไม่ ต้องติดตามในซีรี่ย์สุดระทึกเรื่องนี้",
