    "description": "เรื่องย่อ: โอเอซิส รีสอร์ตซ่อนปม\r\n บอกเล่าเรื่องราวของ โอเอซิส เจ้าของรีสอร์ตหรูหราที่ได้รับการยกย่อง ว่าเป็นสวรรค์แห่งการพันผ่อนสำหีบเหล่ามหาเศรษฐี ด้วยชายหาดส่วนตัว สิ่งอำนวยความสะดับระดับวีไอพี และระบบรักษาความปลอดภัยที่แน่นหนาจนดูเหมือนไร้ช่องโหว่ แต่เบื้องหลังความสมบูรณ์แบบนั้นกลับซ่อนความลับดำมืดเอาไว้ เมื่อเกิดเหตุการณ์การหายตัวไปอย่างลึกลับของบุคคลหนึ่งภายในรีสอร์ต ทำให้เจ้าหน้าที่ตำรวจบุกเข้ามาสืบสวนคดี ทุกคนที่อยู่ในสถานที่แห่งนี้ ไม่ว่าจะเป็นแขกผู้เข้าพักหรือพนักงาน ต่างตกเป็นผู้ต้องสงสัยทันที และไม่มีใครได้รับอนุญาตให้ออกจากรีสอร์ตจนกว่าจะพบความจริง แต่แล้วท่ามกลางบรรยากาศของความหรูหราหมาเห่า พร้อมความหวาดระแวงพพร้อมทุกอย่างจึงเริ่มคืบคลานเข้ามามากขึ้นเรื่อยๆ\r\n",
