    "description": "เรื่องย่อ-แฟนสมมติ สะดุดรัก\r\n  บอกเล่าเรื่องราวของหญิงสาวคนหนึ่งอย่าง ซอมีแร เมื่อเธอได้เข้ามาทำงานในหน้าที่โปรดิวเซอร์ผู้บ้างานแต่เธอจนไม่มีเวลารักตัวเองเลยแม้แต่น้อย แต่ด้วยความสิ้นหวังเธอกับเลือกที่จะเข้ามาเลือกใช้บริการหาแฟนแบบสมมุติ หรือแฟนรายเดือน พร้อมการออกแบบในชั่วข้ามคืนทุกอย่างที่เป็นเหมือนดั่งความฝันที่เธอเคยคิดมาก่อน พัคคยองนัม คู่แข่งตัวดีที่ทั้งสองต้องเข้ามาร่วมงานกันในตอนนี้ แต่เธอกับได้พยายามเก็บซ่อนความจริงทุกอย่างเอาเอาไว้มาโดยตลอด ด้วยความสิ้นหวังและหมดหนทางที่ต้องทำให้เธอต้องเผชิญหน้ากับความสัมพันธ์ที่ถูกสร้างถูกจนมาถึงตอนนี้ ทว่าทุกอย่างกลับกลายเป็นความรักที่กำลังผลิบานมากยิ่งขึ้น สำหรับซีรี่ย์เรื่องก็สามารถรับชมไปกันได้บนช่องทาง Netflix และรับชมได้พร้อมกันแล้วในวันที่ 6 มีนาคม 2026 โดยมีกันทั้งหมด 10 เท่านั้นพร้อมพากย์ไทยให้แฟนๆได้รับชมไปพร้อมกันแล้วใน  สานต่อความสนุกและความอินเลิฟไปพร้อมกันกับเราต่อได้ที่ G4 แหล่งรวมซีรี่ย์ออนไลน์ที่เรามีมากกว่าสามพันเรื่อง ต้องบอกเลยว่าซีรี่ย์เรื่องนี้จะไม่ทำให้คนดูต้องผิดหวังอย่างแน่นอน   \r\n",
