    "sourceType": "embed",
    "description": "เรื่องย่อ: กรงขังแห่งเงา | 樊笼 泰语版\r\n “เรื่องราวการล้างแค้นท่ามกลางดลกอันโหดร้ายของเหล่ายุทธกาล เรื่องราวเริ่มต้นที่ หนานเยี่ยนจือ บุตรสาวเพียงคนเดียวของช่างฝีมือผู้มีชีวิตเรียบง่าย และแล้วครอบครัวของเธอจึงต้องเผชิญหน้ากับโศกนาฏกรรมครั้งใหญ่ในชีวิต ด้วยการถูกสังหารอย่างดหดเหี้ยม กลับเหลือไว้เพียงปริศนาและเบาะแสเล็กน้อย ว่าใครเป็นคนอยู่เบื้องหลังเหตุการณ์ที่ได้เกิดขึ้นในครั้งนี้ ด้วยการตัดสินใจอยางสิ้นหวังเธอกลับเลือกเข้ามาขอเป็นศิษย์ของ จวงอู๋จิ๋ว หญิงสาวผู้ลึกลับแต่กลับเต็มไปแล้วฝีมือการต่อสู้อย่าล้ำเริศและความลับที่ถูกเก็บซ่อนอีกมากมาย เพื่อฝึกฝนความแข็งแกร่งให้เพียงพอ สำหรับการแก้แค้น เมื่อ หนานเยี่ยนจือ จากหญิงสาวผู้ไร้เดียงสากลับกลายเป็นนักสู้ที่แข็งแกร่ง พร้อมการเข้ามาแฝงตัวเข้ามาใน หอหลิงหยา ซึ่งเป็นสถานที่ที่น่ากลัวที่ถูกพูดถึงว่าเป็นที่แห่งการแข่งขันที่ผู้แพ้กลับไม่สามารถเอาชีวิตกลับมาได้ เพื่อการสืบหาความจริงว่าใครเป็นคนลงมือทำกับครอบครัวของเธอ แต่แล้วเมื่อเธอได้พบกับ จวงอู๋จิ๋ว กลับเป็นเจ้าสำนักแห่งพื้นที่สุดอันตรายแห่งนี้  \r\n",
