    "videoUrl": "https://torbo007.com/embed/f6a7f51060785c513e8fed647cd70b09",
    "sourceType": "embed",
    "description": "พล็อตเรื่อง:กงสีสีหมึก | 家业\r\n  เมื่อเรื่องราวความขัดแย้งในช่วงยุคสมัยราชวงศ์หมิง เมื่อวงการผลิตหมึกเริ่มรุ่งเรือง แต่แล้วทุกอย่างต้องดับสูญลงอีกครั้ง ด้วยวิกฤตครั้งใหญ่จากกฎหมายหมึกบรรณการ จนทุกอย่างเริ่มทำให้ตระกูลเก่าแก่ต้องล้มสลายและสูญเสียอำนาจกาค้าไปอย่างกระทันหัน ในท่ามกลางความวุ่นวาย หลี่เจิน บุตรสาวเพียงคนเดียวจากตระกูลผู้ต้อยต่ำ ต้องกลับมาต่อสู้เพื่อกอบกู้ชื่อเสียงของตระกูลอีกครั้ง ด้วยพรสวรรค์ ความมุ่งมั่น และความพยายามที่ไม่ยอมแพ้ หลี่เจิน ที่ได้เริ่มสร้างวงการหมึกขึ้นมาอีกครั้ง และพร้อมการลงแข่งขันและเล่ห์เหลี่ยมทางธุรกิจ ในขณะเดียวกันนั้น ลั่วเหวินเชียน ทายาทหนุ่มเพียงคนเดียวจากตระกูลใหญ่ ที่พยายามฟื้นฟูกิจการของตระกูลเช่นเดียวกัน ดูเหมือนว่าจุดมุ่งหมายของทั้งคู่เริ่มชี้ไปในทางเดียวกัน ทั้งสองจึงร่วมตัดสินใจกลับมาร่วมมือกันฝ่าฟันอุปสรรค์อีกครั้ง จนกระทั่งทุกอย่างเริ่มกลายเป็นความสัมพันธ์อันลึกซึ่งในท่ามกลางความขัดแย้งเหล่านี้ สุกท้ายแล้วเรื่องราวความรักผิดที่ผิดเวลาของบ่าวสาวคู่นี้จะเป็นมาอย่างไรเรไาปรับชมพร้อมๆกันค่ะ>>",
