    "videoUrl": "https://torbo007.com/embed/3f0ed100b1f9ed6bbbd172c9bc330c31",
    "sourceType": "embed",
    "description": "เรื่องย่อ: บันทึกคดีแดนใต้ | 南部档案\r\n ซีรี่ย์จีนแนวสืบสวน ลึกลับ และผจญภัย ที่พาผู้ชมดำดิ่งสู่ยุคสาธารณรัฐจีน เมื่อเหตุฆาตกรรมปริศนาและเรื่องราวเหนือธรรมชาติเกิดขึ้นกลางทะเลใต้ สองเจ้าหน้าที่จากหน่วยสืบสวนลับต้องออกตามหาเบาะแสที่นำไปสู่ความลับอันดำมืดขององค์กรลึกลับ การสมคบคิดของผู้มีอำนาจ และปริศนาที่เชื่อมโยงกับตระกูลเก่าแก่ ท่ามกลางอันตรายที่รออยู่ทุกย่างก้าว พวกเขาจึงต้องเสี่ยงชีวิตเพื่อเปิดโปงความจริงที่อาจเปลี่ยนชะตากรรมของผู้คนมากมายไปตลอดกาล บอกเล่าเรื่องราวของ จางไห่เหยียน รับบทโดย (จางซินเฉิง) และเพื่อนสนิทอย่าง จางไห่เสีย รับบทโดย (ติงอวี่ซี) สองเจ้าหน้าที่หนุ่มที่ได้รับมอบหมายให้เข้ามาสื่อคดีที่ไม่สามารถปิดจบในเวลาที่กำหนด เล่าเรื่อง ติงอวี่ซี รับบทเป็น “จางไห่เสีย” และ จางซินเฉิง รับบทเป็น “จางไห่เหยียน” สองเจ้าหน้าที่หน่วนงานสืบสวนจากหน่วยหอจดหมายเหตุแดนใต้ ที่ได้รับมอบหมายให้ไขคดีฆาตกรรมปริศนาและเหตุการณ์ลึกลับกลางทะเลหนานหยาง। ระหว่างการสืบสวน พวกเขาค้นพบเบาะแสที่เชื่อมโยงกับองค์กรลับและแผนสมคบคิดอันตรายที่ซ่อนอยู่เบื้องหลังหลายปี। ท่ามกลางการไล่ล่าและอันตรายรอบด้าน ทั้งคู่ต้องเสี่ยงชีวิตเพื่อเปิดเผยความจริงที่ถูกปกปิดเอาไว้   ",
