    "description": "เรื่องย่อ: แล้วเราจะพบกัน\r\n  เป็นอีกหนึ่งเรื่องราวของ เดวิด เบอร์โรห์ส ชายหนุ่มผู้ถูกตัดสินให้จำคุกไปตอลดชีวิต ในข้อหาการฆาตกรรมลูกชายของตนเอง แม้ว่าเขาจะพยายามยืนหยัดในความจริงว่าเขาไม่ใช่คนลงมือทำ สุดท้ายแล้วชีวิตในคุกเขากลับไม่รอด จากการใช้ชีวิตในเรือนจำ เดวิด เปลี่ยนไปเมื่อมีหลักฐานใหม่ปรากฎขึ้นมากอีกครั้ง ซึ่งเรื่องราวทุกอย่างพยายามชี้เกี่ยวกับเรื่องราวของลูกชายเขาเอง ที่ว่าเสียชีวิตไปอย่างปริศนา แล้วอาจะมีชีวิตอยู่ด้วยความหวังครั้งนี้จึงทำให้เขาตัดสินใจเสี่ยงความเป้นความตายทุกอย่างเพื่อการหลบหนีออกจากคุกแห่งนี้ และออกตามหาความจริงที่ถูกเก็บซ่อนไว้กับเบื้องหลังคดีสะเทือนขวัยครอบครัวของตนเองอีกครั้ง ในระหว่างการสืบหาความจริงนั้น เดวิล กลับต้องเผชิญหน้ากับเครือข่ายของความลับ การหลอกลวง และบุคคลิกมากมายที่อาจเกี่ยวข้องกับความจริงการหายตัวไปของลุกชายเขาเท่านั้น",
