    "sourceType": "embed",
    "description": "เรื่องย่อ: คู่มือฆาตกรรมฉบับเด็กดี 2\r\n หลังจากเหตุการณ์ในคดีแรก พิปพยายามกลับไปใช้ชีวิตปกติและทิ้งโลกแห่งการสืบสวนไว้เบื้องหลัง แต่ความสงบกลับอยู่ได้ไม่นาน เมื่อมีคดีปริศนาใหม่เกิดขึ้นในเมืองอีกครั้ง พร้อมการหายตัวไปของบุคคลสำคัญที่เกี่ยวข้องกับเธอโดยตรง แม้ไม่อยากเข้าไปยุ่ง แต่พิปกลับพบว่าหลักฐานหลายอย่างเต็มไปด้วยความผิดปกติ และยิ่งสืบลึกลงไป เธอก็ยิ่งพบว่าคดีนี้อันตรายกว่าที่คิด เพราะเบื้องหลังเกี่ยวพันกับความลับดำมืด การโกหก และคนใกล้ตัวที่อาจซ่อนตัวตนที่แท้จริงเอาไว้ ในการสืบครั้งใหม่ พิปต้องเผชิญทั้งแรงกดดันจากสังคม ความหวาดกลัว และผลกระทบจากอดีตที่ยังตามหลอกหลอน ขณะเดียวกันความสัมพันธ์ระหว่างเธอกับคนรอบข้างก็เริ่มเปลี่ยนไป เมื่อความจริงบางอย่างกำลังจะถูกเปิดเผย\r\n",
