    "year": 2026,
    "poster": "https://goseries4k.com/wp-content/uploads/2026/02/88.jpg",
    "backdrop": "https://goseries4k.com/wp-content/uploads/2026/02/88.jpg",
    "videoUrl": "https://torbo007.com/embed/bd9aba65439ef7b92da21d791b99eac9",
    "sourceType": "embed",
    "description": "เรื่องย่อ : หัวใจใฝ่หา วลาดิเมียร์ | VLADIMIR\r\n หญิงสาวคนหนึ่งเพิ่งก้าวเข้าสู่ชีวิตแต่งงานกับนักเขียนหนุ่มผู้โด่งดังและเปี่ยมไปด้วยไฟฝัน\r\nเธอเคยเชื่อว่าการได้เป็นภรรยาของชายผู้ประสบความสำเร็จจะเติมเต็มชีวิตด้วยความสุขและความภาคภูมิใจ แต่หลังพิธีวิวาห์ผ่านพ้นไป สิ่งที่เหลืออยู่กลับเป็นเพียงบ้านที่เงียบงันและหัวใจที่ว่างเปล่า\r\nสามีของเธอหมกมุ่นอยู่กับงานเขียนและชื่อเสียง จนแทบไม่มีพื้นที่เหลือให้ความรัก ความโดดเดี่ยวค่อยๆ กัดกินความรู้สึกของเธอทีละน้อยโดยไม่มีใครสังเกตเห็น จนกระทั่งวันหนึ่ง เธอบังเอิญได้พบกับชายหนุ่มแปลกหน้าที่มองเธอราวกับเธอมีความหมาย สายตาและบทสนทนาสั้นๆ กลับจุดประกายบางอย่างที่เธอคิดว่าสูญหายไปแล้ว ความสัมพันธ์ที่เริ่มจากความบังเอิญค่อยๆ พัฒนาเป็นความลับที่ทั้งคู่เฝ้าถนอมและปกปิด พวกเขาต่างรู้ดีว่าสิ่งที่ทำอยู่นั้นผิดศีลธรรม แต่ความต้องการทางใจกลับรุนแรงเกินห้าม ท้ายที่สุด เธอต้องเลือกระหว่างชีวิตแต่งงานที่ว่างเปล่ากับความรักต้องห้ามที่อาจเผาทำลายทุกอย่างจนไม่เหลืออะไรเลย\r\n",
