    "videoUrl": "https://torbo007.com/embed/fd84d8f399eb6b36733b4e71bb20c8f8",
    "sourceType": "embed",
    "description": "เรื่องย่อ หนี RUN AWAY\r\n เมื่อครอบครัวที่สุขสันต์ “ไซมอน” ที่มีภรรยาและลูกสาวอันสมบูรณ์แบบ ทว่าความสุขที่อยู่ได้ไม่นานจนกระทั้งเมื่อลูกสาวของได้หนีออกจากบ้านไป และนี่จึงทำให้เขาได้ออกตามหาและได้พบกว่าลูกสาวของเขาได้เข้ามามั่วสุมอยู่กับแหลางยาเสพติด และเขาก็ได้พบว่าลูกสาวของเขาเองก็ไม่ได้อยู่คนเดียว และนี่เองเขาจึงได้โอกาสได้จับลูกสาวของกลับมาบ้านอีกครั้งและ แต่หลายวันต่อมาลูกสาวของเขาได้หายตัวไปอีกครั้งและในครั้งลูกสาวของเขากลับต้องเข้าไปอยู่ในโลกอันดำมืดอีกครั้ง และนี่เองจึงทำให้เขาต้องกลับมาเปิดโปรงความจริงที่มืดมิดอีกครั้ง แต่แล้วเขาจะสามารถนำพาให้ลูกสาวเพียงคนเดียวของเขาออกมาจากโคจรอันดำมืดเหล่านี้ได้หรือไม่ และแล้วซีรี่ย์เรื่องนี้จะจบลงอย่างไรเราไปรับชมพร้อมๆกันค่ะ สำหรับซีรี่ย์เรื่องนี้ก็พร้อมออกอากาศในวันที่ 1 มกราคม 2026 จำนวน 8 ตอนเพียงเท่านั้น ทั้งยังมาในรูปแบบพากย์ไทยให้แฟนได้เลือกรับชมกันได้อย่างตามใจชอบ สานต่อความสนุกไปพร้อมกันกับพวกเราได้ที่ G4 แหล่งรวมซีรี่ย์ออนไลน์ ครบ จบ ในที่เดียว \r\n",
